from lib import *
S = SS('s43')
steps = [
    step("用 grep 数 Scrapy 2.19 源码里读写的 request.meta 键:共 45 个,其中公开的 40 个、下划线开头的内部键 5 个(_auth_proxy、_callback、_depth、_dont_cache、_scheme_proxy)。按用途分:你设置的输入键 24 个(allow_offsite、autothrottle_dont_adjust_delay、bindaddress、cookiejar、depth_reset、dont_cache、dont_merge_cookies、dont_obey_robotstxt、dont_redirect、dont_retry、download_maxsize、download_slot、download_timeout、download_warnsize、handle_httpstatus_all、handle_httpstatus_list、http_auth_domain、http_pass、http_user、max_retry_times、priority_adjust、proxy、referrer_policy、verbatim_url,另有 give_up_log_level 在重试中间件里读取);Scrapy 写入的输出键 10 个(cache_timestamp、depth、download_latency、is_start_request、redirect_reasons、redirect_times、redirect_ttl、redirect_urls、retry_times、rule)。另有 FTP 相关的 ftp_user、ftp_password、ftp_passive、ftp_local_filename,以及 is_secure、cached_response 等。", t=tl(S(1)), mark=lidx(S(1), '共 45', '公开键', '内部键'), done=lidx(S(1), '按用途分', '源码里出现'), kv=KV([['全部', '45 个(公开 40 + 内部 5)'], ['输入键', '24 个:dont_*、download_*、handle_httpstatus_*、proxy、cookiejar …'], ['输出键', '10 个:depth、redirect_*、retry_times、download_latency …'], ['FTP 相关', 'ftp_user / ftp_password / ftp_passive / ftp_local_filename']], ['输入键'])),
    step("几个前面没单独讲的输入键(每个请求单独设):download_timeout = 0.3 让 1 秒的 /slow 超时 → errback DownloadTimeoutError(不设则回调 200);download_maxsize = 1000 让 5000 字节的 /big → errback DownloadCancelledError(不设则回调拿到 5000 字节);handle_httpstatus_all = True 让 404 进回调(不设 → errback HttpError);handle_httpstatus_list = [500] 只放行 500 → 500 进回调,503 仍然 errback HttpError。", t=tl(S(2)), mark=lidx(S(2), 'download_timeout', 'download_maxsize'), done=lidx(S(2), 'handle_httpstatus_all', 'handle_httpstatus_list'), kv=KV([['download_timeout', '这个请求单独的超时(秒)'], ['download_maxsize', '这个请求单独的响应大小上限'], ['handle_httpstatus_all', '所有状态码都进回调'], ['handle_httpstatus_list', '只放行列表里的状态码']], ['download_timeout'])),
    step("bindaddress(本地出口地址):不设和 ('127.0.0.1', 0) 都由 127.0.0.1 出去,服务器看到的客户端地址一样;('10.255.255.1', 0) 本机没有这个地址,errback 收到 ConnectBindError,消息 “Couldn't bind: 49: Can't assign requested address.”,服务器没收到请求。", t=tl(S(3)), mark=lidx(S(3), '10.255.255.1'), kv=KV([['bindaddress = (ip, 0)', '指定本地出口 IP'], ['本机没有的地址', 'ConnectBindError']], ['bindaddress = (ip, 0)'])),
    step("referrer_policy:页面 /link?q=1#frag 上跟随链接到 /landing,默认(scrapy-default)的 Referer 是 http://主机/link?q=1(去掉片段的完整 URL);'no-referrer' 没有 Referer 头;'origin' 只剩 http://主机/;'same-origin'、'strict-origin-when-cross-origin'、'unsafe-url' 在同源 http 下都是完整 URL。", t=tl(S(4)), mark=lidx(S(4), 'no-referrer', 'origin  '), done=lidx(S(4), 'None', 'unsafe-url'), kv=KV([['默认', '完整 URL(去掉片段)'], ['no-referrer', '不发 Referer'], ['origin', '只发源(协议 + 主机 + 端口 + /)']], ['no-referrer'])),
    step("请求级 Basic 认证(2.19):meta 里 http_user / http_pass → Authorization 头 alice:s3cret;http_auth_domain = localhost 而请求在 127.0.0.1 → 不发;请求自带 Authorization 头时不覆盖(Bearer own)。设置级 HTTPAUTH_USER / HTTPAUTH_PASS 必须同时设 HTTPAUTH_DOMAIN,否则启动即 ValueError。坑:域名匹配用的是 URL 的 netloc(含端口),HTTPAUTH_DOMAIN = 127.0.0.1 对 http://127.0.0.1:端口/ 的请求不匹配(没有 Authorization),必须写成 127.0.0.1:<端口>;meta 的 http_auth_domain 同理。", t=tl(S(5)), mark=lidx(S(5), 'HTTPAUTH_DOMAIN=127.0.0.1(不带端口', '域名带上端口', 'ValueError'), done=lidx(S(5), 'meta http_user/http_pass', 'meta http_auth_domain=127.0.0.1'), kv=KV([['meta http_user / http_pass', '单个请求的认证'], ['HTTPAUTH_USER / PASS', '必须配 HTTPAUTH_DOMAIN,否则启动失败'], ['域名匹配', '用 netloc(含端口):URL 有端口,域名也得带端口'], ['自带 Authorization 头', '不被覆盖']], ['域名匹配'])),
    step("一个请求经过起始、302 重定向、503 重试、Set-Cookie 之后,response.meta 里最终有 10 个键:自己放的 mine,加上 Scrapy 写入的 download_latency、download_slot(127.0.0.1)、download_timeout、is_start_request(True)、redirect_reasons([302])、redirect_times(1)、redirect_ttl(19)、redirect_urls、retry_times(1)。这些是输出键,response.follow 产生的新请求不继承它们。", t=tl(S(6)), mark=lidx(S(6), '共 10 个键'), done=lidx(S(6), '其中的取值'), kv=KV([['自己放的', 'mine'], ['下载器写的', 'download_latency / slot / timeout'], ['重定向写的', 'redirect_reasons / times / ttl / urls'], ['重试写的', 'retry_times = 1']], ['下载器写的'])),
]
A = mkarts('s43', 43, 'Scrapy,request.meta,特殊键,download_timeout,referrer_policy,http_user,真实验证,动画演示',
    '从 Scrapy 2.19 源码 grep 出 45 个 request.meta 键(公开 40、内部 5;输入键 24、输出键 10)并实测前面没讲过的:download_timeout、download_maxsize、handle_httpstatus_*、bindaddress、referrer_policy;请求级 Basic 认证 http_user / http_pass,以及 HTTPAUTH_DOMAIN 因匹配 netloc(含端口)而对带端口的 URL 失效的坑。',
    'request.meta 是 Scrapy 里最杂的一个字典:既有你写给 Scrapy 的开关,也有 Scrapy 写给你的记录。这篇从源码里把所有键列出来分类,再把前面没单独验证过的几个开关一一实测。',
    [('45 个', 'Scrapy 2.19 源码里读写的 request.meta 键总数(公开 40、内部 5)'), ('24 / 10', '其中你设置的输入键数 / Scrapy 写入的输出键数'), ('含端口', 'HTTPAUTH_DOMAIN 匹配 URL 的 netloc,对带端口的 URL 必须写端口')],
    [('输入键与输出键', '<p>输入键(<code>dont_redirect</code>、<code>download_timeout</code>、<code>proxy</code> 等)改变这个请求怎么被处理;输出键(<code>depth</code>、<code>redirect_*</code>、<code>retry_times</code>、<code>download_latency</code> 等)是中间件写给你的记录。下划线开头的是内部键,别碰。</p>'),
     ('请求级的覆盖', '<p><code>download_timeout</code>、<code>download_maxsize</code>、<code>handle_httpstatus_all/list</code> 可以只对一个请求覆盖全局设置。</p>'),
     ('出口地址', '<p><code>bindaddress</code> 指定本地出口,本机没有的地址会得到 <code>ConnectBindError</code>。</p>'),
     ('Referer 策略', '<p><code>referrer_policy</code> 决定跟随链接时发什么 Referer:不发、只发源、或完整 URL。</p>'),
     ('认证', '<p><code>http_user</code> / <code>http_pass</code> 给单个请求加 Basic 认证,设置级的认证必须配域名;域名匹配的是含端口的 netloc。</p>'),
     ('最终有哪些键', '<p>经过重定向、重试等中间件后,response.meta 里会多出一批输出键;它们不会被 <code>response.follow</code> 继承。</p>')],
    steps,
    [ENV_Y + '。第一节在虚拟环境里 grep Scrapy 源码(只做了字面匹配,键名可能漏掉用变量拼出来的);其余每项是单文件 spider 对本机服务器的实测',
     '没有验证:ftp_*、is_secure(FTP 处理器)的键;cache_timestamp、cached_response(HTTP 缓存内部);verbatim_url 的细节(指纹那一篇测过);给 give_up_log_level 设值的效果;其它第三方项目(如 scrapy-playwright)自己定义的 meta 键;键名的 grep 清单可能含个别误报或遗漏'],
    'request.meta 的键')
